WITH with_latest AS (SELECT s.*, latest.order_discount FROM stores s LEFT JOIN LATERAL (SELECT c.discount AS order_discount FROM orders c WHERE c.store_id = s.id AND c.order_date <= s.opened_date ORDER BY c.order_date DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT CASE WHEN sqft >= 16607 THEN 'HIGH' ELSE 'LOW' END AS sqft_tier, DATE_TRUNC('WEEK', opened_date) AS week_start, ROUND(AVG(order_discount), 2) AS avg_order_discount, BIT_AND(sqft) AS sqft_bit_and, AVG(order_discount) AS avg_order_discount_2, DENSE_RANK() OVER (PARTITION BY CASE WHEN sqft >= 16607 THEN 'HIGH' ELSE 'LOW' END ORDER BY BIT_AND(sqft) DESC) AS sqft_bit_and_dense_rank FROM with_latest GROUP BY 1, 2 ORDER BY sqft_tier DESC NULLS FIRST;
